text:
&.button-advanced-configuration {
  display: flex;
  /* There should be 12px between the bottom of this button, and the top of
   * the footer buttons. We need to factor in the footer button's top margin,
   * and the 2px top padding of the 'dialog-menu-container' class */
  margin-block-end: calc(12px - var(--button-margin) - 2px);
  margin-inline-start: auto;
  /* This is needed to align the link with the footer buttons correctly. The
   * 10px comes from menu.dialog-menu-container in inContentDialog.css  */
  margin-inline-end: calc(var(--button-border-size) + var(--button-margin) + 10px);
  padding: var(--hub-space-medium) var(--space-step);
  text-decoration: underline;
  font-weight: 500;
  border: 0;
}
